-- 2026-11-07u UNDO: puts back the background timelines and checked dates of the 54 MPs changed by 2026-11-07u-background-new.sql
-- (member_ids 5282, 5283, 5286, 5287, 5288, 5289, 5291, 5292, 5293, 5294, 5295, 5296, 5299, 5300, 5303, 5304, 5306, 5307, 5310, 5312, 5313, 5316, 5317, 5318, 5319, 5320, 5321, 5322, 5324, 5325, 5326, 5327, 5329, 5331, 5333, 5335, 5336, 5338, 5339, 5341, 5342, 5343, 5345, 5348, 5350, 5352, 5356, 5357, 5359, 5360, 5361, 5362, 5403, 5450), exactly as they were when the migration was generated on 2026-11-07
-- (backup off the repo: "Claude outputs/backups/2026-11-07u-mp-biography-before.csv"). Each row changes only WHERE it still holds the
-- 2026-11-07u array (md5), so a later edit is never overwritten silently. No other row changes.
-- Guards (RAISE): exactly 54 rows change; nothing else changes; MPs with a timeline 650 to 596; 7,124 entries.
\set ON_ERROR_STOP on
BEGIN READ WRITE;
SET LOCAL statement_timeout = '60s';
SET LOCAL lock_timeout = '5s';

CREATE TEMP TABLE bt_before ON COMMIT DROP AS
SELECT member_id, md5(to_jsonb(b)::text) AS h FROM public.mp_biography b;

CREATE TEMP TABLE bt_restore (member_id integer PRIMARY KEY, tl jsonb, checked date, cur_md5 text NOT NULL) ON COMMIT DROP;

DO $$ BEGIN
  IF (SELECT count(*) FROM public.mp_biography b JOIN bt_restore r USING (member_id) WHERE md5(b.background_timeline::text) = r.cur_md5) <> 54 THEN
    RAISE EXCEPTION 'a timeline is not the 2026-11-07u value (changed since)';
  END IF;
END $$;

UPDATE public.mp_biography b SET background_timeline = r.tl, background_last_checked = r.checked
  FROM bt_restore r WHERE b.member_id = r.member_id AND md5(b.background_timeline::text) = r.cur_md5;

DO $$
DECLARE
  changed integer;
  changed_outside integer;
  restored integer;
  with_timeline integer;
  entry_total integer;
BEGIN
  SELECT count(*) INTO changed FROM public.mp_biography b JOIN bt_before o USING (member_id) WHERE md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO changed_outside FROM public.mp_biography b JOIN bt_before o USING (member_id)
   WHERE b.member_id NOT IN (5282, 5283, 5286, 5287, 5288, 5289, 5291, 5292, 5293, 5294, 5295, 5296, 5299, 5300, 5303, 5304, 5306, 5307, 5310, 5312, 5313, 5316, 5317, 5318, 5319, 5320, 5321, 5322, 5324, 5325, 5326, 5327, 5329, 5331, 5333, 5335, 5336, 5338, 5339, 5341, 5342, 5343, 5345, 5348, 5350, 5352, 5356, 5357, 5359, 5360, 5361, 5362, 5403, 5450) AND md5(to_jsonb(b)::text) IS DISTINCT FROM o.h;
  SELECT count(*) INTO restored FROM public.mp_biography b JOIN bt_restore r USING (member_id)
   WHERE b.background_timeline IS NOT DISTINCT FROM r.tl AND b.background_last_checked IS NOT DISTINCT FROM r.checked;
  SELECT count(*) INTO with_timeline FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  SELECT coalesce(sum(jsonb_array_length(background_timeline)), 0) INTO entry_total FROM public.mp_biography WHERE background_timeline IS NOT NULL;
  RAISE NOTICE 'UNDO: rows changed %, outside the 54 %, rows restored exactly %, MPs with a timeline %, entries %', changed, changed_outside, restored, with_timeline, entry_total;
  IF changed <> 54 THEN RAISE EXCEPTION 'expected exactly 54 rows changed, got %', changed; END IF;
  IF changed_outside <> 0 THEN RAISE EXCEPTION '% rows outside the 54 changed', changed_outside; END IF;
  IF restored <> 54 THEN RAISE EXCEPTION 'expected 54 rows restored exactly, got %', restored; END IF;
  IF with_timeline <> 596 THEN RAISE EXCEPTION 'expected 596 MPs with a timeline, got %', with_timeline; END IF;
  IF entry_total <> 7124 THEN RAISE EXCEPTION 'expected 7124 entries, got %', entry_total; END IF;
END $$;

COMMIT;
